/* empty css                                                                            */import{c as t,o as r,a1 as e}from"./chunks/framework.Be0jKih-.js";const o=e('<h1 id="projektuppgif-bs-bibliotekssystem" tabindex="-1">Projektuppgif bs: Bibliotekssystem <a class="header-anchor" href="#projektuppgif-bs-bibliotekssystem" aria-label="Permalink to &quot;Projektuppgif bs: Bibliotekssystem&quot;">​</a></h1><p>I denna uppgift ska du skapa ett system för att hantera böcker, låntagare och bibliotek. Uppgiften består av tre nivåer där varje nivå bygger vidare på den tidigare.</p><h2 id="niva-for-betyg-e" tabindex="-1">Nivå för betyg E: <a class="header-anchor" href="#niva-for-betyg-e" aria-label="Permalink to &quot;Nivå för betyg E:&quot;">​</a></h2><p>Skapa klasserna <strong>Book</strong>, <strong>Member</strong>, och <strong>Library</strong> enligt beskrivningen nedan.</p><ol><li><p>Klass <strong>Book</strong></p><ul><li>Attribut: <ul><li><strong>title</strong> (titel på boken)</li><li><strong>author</strong> (författare)</li></ul></li><li>Metoder: <ul><li><strong>__init__</strong> - En initieringsmetod som tar emot titel och författare som argument.</li><li><strong>__str__</strong> - En metod som returnerar en sträng som beskriver boken, t.ex. &quot;Titel av Författare&quot;.</li></ul></li></ul></li><li><p>Klass <strong>Member</strong></p><ul><li>Attribut: <ul><li><strong>name</strong> (namn på medlemmen)</li></ul></li><li>Metoder: <ul><li><strong>__init__</strong> - Tar emot namn som argument.</li><li><strong>__str__</strong> - Returnerar medlemmens namn.</li></ul></li></ul></li><li><p>Klass <strong>Library</strong></p><ul><li>Attribut: <ul><li><strong>books</strong> - En lista som innehåller alla böcker i biblioteket.</li></ul></li><li>Metoder: <ul><li><strong>__init__</strong> - Skapar en tom lista för böcker.</li><li><strong>add_book</strong> - En metod som lägger till en bok i biblioteket.</li><li><strong>display_books</strong> - En metod som skriver ut alla böcker i biblioteket.</li></ul></li></ul></li></ol><h2 id="niva-for-betyg-c" tabindex="-1">Nivå för betyg C: <a class="header-anchor" href="#niva-for-betyg-c" aria-label="Permalink to &quot;Nivå för betyg C:&quot;">​</a></h2><p>Utöka systemet med <strong>arv</strong>.</p><ol><li><p>Klass <strong>LibraryMember</strong> (arv från <strong>Member</strong>):</p><ul><li>Attribut: <ul><li><strong>borrowed_books</strong> - En lista som innehåller de böcker som medlemmen lånat.</li></ul></li><li>Metoder: <ul><li><strong>borrow_book</strong> - Låter medlemmen låna en bok och lägger till boken i borrowed_books.</li><li><strong>return_book</strong> - Låter medlemmen lämna tillbaka en bok. Boken tas bort från listan borrowed_books.</li></ul></li></ul></li><li><p>Modifiera klassen <strong>Library</strong>:</p><ul><li>Lägg till en metod <strong>loan_book</strong> som låter en medlem låna en bok om den är tillgänglig.</li><li>Lägg till en metod <strong>return_book</strong> som tar tillbaka en bok från en medlem.</li></ul></li></ol><h2 id="niva-for-betyg-a" tabindex="-1">Nivå för betyg A: <a class="header-anchor" href="#niva-for-betyg-a" aria-label="Permalink to &quot;Nivå för betyg A:&quot;">​</a></h2><p>Implementera abstrakta klasser, polymorfism, överlagring, och generiska klasser.</p><ol><li>Skapa en abstrakt klass <strong>LibraryItem</strong>: <ul><li><strong>LibraryItem</strong> ska vara en abstrakt basklass för <strong>Book</strong> och <strong>Magazine</strong>.</li><li>Lägg till en abstrakt metod <strong>get_info</strong> som returnerar information om objektet.</li></ul></li><li>Skapa en generisk klass <strong>Container</strong> som kan hantera olika typer av <strong>LibraryItem</strong>-objekt.</li></ol>',11),i=[o],m=JSON.parse('{"title":"Projektuppgif bs: Bibliotekssystem","description":"","frontmatter":{"outline":[1,6]},"headers":[],"relativePath":"programming2/task/task1.md","filePath":"programming2/task/task1.md"}'),l={name:"programming2/task/task1.md"},k=Object.assign(l,{setup(n){return(a,s)=>(r(),t("div",null,i))}});export{m as __pageData,k as default};
